--
-- Name: actualizar_dashboard_agrupado(); Type: FUNCTION; Schema: public; Owner: admin_comunidad
--

CREATE FUNCTION public.actualizar_dashboard_agrupado() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Eliminar todos los registros
    DELETE FROM dashboard_agrupado;
    
    -- Reinsertar con todos los datos (incluyendo animales desde rufe_formularios)
        reporte_id, titulo, estado, fecha, barrio, direccion,
        latitud, longitud, descripcion, ciudadano, telefono,
        total_reportes_grupo, fecha_actualizacion,
        genero, documento, animales_rufe,
        cantidad_perros, cantidad_gatos, cantidad_aves, otros_animales
    )
    SELECT 
        r.id,
        r.titulo,
        r.estado_actual,
        r.fecha_creacion,
        COALESCE(b.nombre, r.sector_barrio, 'SIN CLASIFICAR'),
        r.direccion_referencia,
        r.latitud,
        r.longitud,
        r.descripcion_detallada,
        COALESCE(r.datos_extra->>'ciudadano', 'Anónimo'),
        COALESCE(r.datos_extra->>'telefono', 'No registra'),
        1,
        NOW(),
        r.datos_extra->>'genero',
        r.datos_extra->>'documento',
        rf.observaciones_animales,
        0,
        0,
        0,
        NULL
    FROM 
        reportes_comunitarios r
    LEFT JOIN barrios b ON r.barrio_id = b.id
    LEFT JOIN rufe_formularios rf ON r.id = rf.reporte_id
    WHERE r.estado_actual IN ('PENDIENTE', 'RECIBIDO', 'EN PROCESO')
       OR r.fecha_creacion >= NOW() - INTERVAL '30 days';
    
    RAISE NOTICE '✅ Dashboard actualizado con % registros', (SELECT COUNT(*) FROM dashboard_agrupado);
END;
$$;


ALTER FUNCTION public.actualizar_dashboard_agrupado() OWNER TO admin_comunidad;

