--
-- Name: reportes_unicos; Type: VIEW; Schema: public; Owner: admin_comunidad
--

CREATE VIEW public.reportes_unicos AS
 SELECT id,
    titulo,
    estado_actual,
    fecha_creacion,
    sector_barrio,
    direccion_referencia,
    latitud,
    longitud,
    descripcion_detallada,
    COALESCE((datos_extra ->> 'ciudadano'::text), 'Anónimo'::text) AS ciudadano,
    COALESCE((datos_extra ->> 'telefono'::text), 'Sin teléfono'::text) AS telefono,
    datos_extra,
    1 AS total_reportes_grupo
   FROM public.reportes_comunitarios r;


