--
-- Name: reportes_unificados; Type: VIEW; Schema: public; Owner: admin_comunidad
--

CREATE VIEW public.reportes_unificados AS
 SELECT r.id AS reporte_id,
    r.titulo,
    r.estado_actual AS estado,
    r.fecha_creacion,
    r.sector_barrio AS barrio,
    r.direccion_referencia AS direccion,
    r.latitud,
    r.longitud,
    r.descripcion_detallada AS descripcion,
    r.ultima_actualizacion,
    r.fecha_reporte,
    r.gravedad,
    (r.datos_extra ->> 'ciudadano'::text) AS ciudadano,
    (r.datos_extra ->> 'telefono'::text) AS telefono,
    (r.datos_extra ->> 'documento'::text) AS documento,
    r.datos_extra,
    b.id AS barrio_id,
    b.nombre AS barrio_nombre,
    b.comuna,
    rf.id AS rufe_id,
    rf.numero_formulario AS rufe_numero,
    rf.corregimiento AS rufe_corregimiento,
    rf.prioridad AS rufe_prioridad,
    rf.observaciones_animales AS rufe_animales,
    rf.observaciones_evaluador AS rufe_evaluador,
    ( SELECT json_agg(json_build_object('id', p.id, 'nombre_completo', p.nombre_completo, 'documento_identidad', p.documento_identidad, 'fecha_nacimiento', p.fecha_nacimiento, 'telefono', p.telefono, 'es_jefe_hogar', p.es_jefe_hogar) ORDER BY p.es_jefe_hogar DESC) AS json_agg
           FROM public.rufe_personas p
          WHERE (p.rufe_formulario_id = rf.id)) AS rufe_personas,
    ed.id AS edhas_id,
    ed.codigo_edhas AS edhas_codigo,
    ed.fecha_evaluacion AS edhas_fecha,
    ed.persona_entrevistada AS edhas_entrevistado,
    ed.documento_entrevistada AS edhas_documento,
    ed.telefono_entrevistada AS edhas_telefono,
    ed.direccion AS edhas_direccion,
    ed.barrio_vereda AS edhas_barrio,
    ed.tipo_inmueble AS edhas_inmueble,
    ed.prioridad AS edhas_prioridad,
    ed.clasificacion_afectacion AS edhas_afectacion,
    ed.observaciones_generales AS edhas_observaciones,
    ed.recomendaciones AS edhas_recomendaciones,
    ed.evaluador_nombre AS edhas_evaluador,
    ed.evaluador_documento AS edhas_evaluador_doc,
    ed.datos_completos AS edhas_datos_completos,
    ae.id AS ahe_id,
    ae.numero_folio AS ahe_folio,
    ae.codigo_ahe AS ahe_codigo,
    ae.fecha_entrega AS ahe_fecha,
    ae.departamento AS ahe_departamento,
    ae.municipio AS ahe_municipio,
    ae.vereda_sector AS ahe_sector,
    ae.nombres AS ahe_nombres,
    ae.apellidos AS ahe_apellidos,
    ae.numero_documento AS ahe_documento,
    ae.telefono AS ahe_telefono,
    ae.asistencia_entregada AS ahe_asistencia,
    ae.subsidio_arriendo AS ahe_subsidio,
    ae.observaciones AS ahe_observaciones,
    ae.datos_completos AS ahe_datos_completos,
    ae.creado_en AS ahe_creado_en,
    ( SELECT json_agg(json_build_object('id', t.id, 'estado_anterior', t.estado_anterior, 'estado_nuevo', t.estado_nuevo, 'observacion', t.observacion, 'usuario', t.usuario, 'fecha_cambio', t.fecha_cambio) ORDER BY t.fecha_cambio DESC) AS json_agg
           FROM public.trazabilidad t
          WHERE (t.reporte_id = r.id)) AS historial,
    ( SELECT count(*) AS count
           FROM public.trazabilidad t
          WHERE (t.reporte_id = r.id)) AS total_cambios_estado,
        CASE
            WHEN (rf.id IS NOT NULL) THEN 'RUFE'::text
            WHEN (ed.id IS NOT NULL) THEN 'EDHAS'::text
            WHEN (ae.id IS NOT NULL) THEN 'AHE'::text
            ELSE 'BASICO'::text
        END AS tipo_reporte
   FROM ((((public.reportes_comunitarios r
     LEFT JOIN public.barrios b ON ((r.barrio_id = b.id)))
     LEFT JOIN public.rufe_formularios rf ON ((r.id = rf.reporte_id)))
     LEFT JOIN public.edhas_evaluaciones ed ON ((r.id = ed.reporte_id)))
     LEFT JOIN public.ahe_entregas ae ON ((r.id = ae.reporte_id)))
  ORDER BY r.fecha_creacion DESC;


ALTER VIEW public.reportes_unificados OWNER TO admin_comunidad;

